import{z as m,x as B,o as r,c as A,q as l,j as o,D as e,d as t,s,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"激活：ReLU 与饱和","description":"","frontmatter":{"title":"激活：ReLU 与饱和","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/activation-relu-saturation.md","filePath":"llm/activation-relu-saturation.md","lastUpdated":1791413859000}'),d={name:"llm/activation-relu-saturation.md"};function p(h,a,u,D,L,c){const E=B("Mermaid");return r(),A("div",null,[a[2]||(a[2]=l('<h1 id="激活-relu-与饱和" tabindex="-1">激活：ReLU 与饱和 <a class="header-anchor" href="#激活-relu-与饱和" aria-label="Permalink to &quot;激活：ReLU 与饱和&quot;">​</a></h1><div class="epigraph"><p>逐元素非线性把一串仿射从「仍是一层仿射」里救出来；导数长期接近零，反向增益就被掐断。</p><footer>—— 据 Nair &amp; Hinton, Rectified Linear Units Improve Restricted Boltzmann Machines, ICML 2010；Glorot, Bordes &amp; Bengio, AISTATS 2011 整理</footer></div><p><a href="/llm/linear-layer-bias">线性层与偏置</a>补上 \\(b\\)。本课不重写仿射。缺口是：仿射的复合仍是仿射，再深的 \\(W^{(\\ell)}\\) 也只是一张等效矩阵。必须在层间插入不是仿射的逐元素函数 \\(\\sigma\\)。本课对比饱和激活与 ReLU：前者在幅值大时 \\(\\sigma&#39;\\approx 0\\)，加重消失；后者在正半轴增益为 \\(1\\)，负半轴为 \\(0\\)。GELU、SwiGLU 是后话，这里只把「为何要非线性、饱和如何伤反向」钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个仿射 \\(A_2(A_1 x)\\) 等于一个仿射。没有 \\(\\sigma\\)，深度不增加函数类，只增加参数化同一超平面的方式。分类、语言建模需要的决策面是弯曲的、分区的。缺口是最小的非线性：每个坐标独立地 \\(\\sigma(z_i)\\)，形状不变，不引入新的轴。</p><p>sigmoid \\(\\sigma(z)=(1+\\mathrm{e}^{-z})^{-1}\\)、tanh 把值挤进有界区间，大 \\(|z|\\) 时导数指数变小——这就是饱和。它曾被当作「概率」或「有界特征」的优点，却与<a href="/llm/vanish-explode-grad">梯度消失与爆炸</a>的增益连乘直接冲突。<span class="marginnote">「饱和」就是&quot;输入太大、曲线变平、导数趋近 0&quot;的状态：sigmoid 在 \\(z=0\\) 处导数约 \\(0.25\\)，\\(z=5\\) 时只剩约 \\(0.007\\)，\\(z=10\\) 时约 \\(0.00005\\)。反向传播靠导数把误差往回送，导数接近 0 就等于把回信地址撕掉了。</span>ReLU \\(\\sigma(z)=\\max(z,0)\\) 正半轴不饱和，负半轴硬切。函数类因此变成分段线性，深度开始真正增加折点数量。</p><h3 id="relu-不是「不会消失」" tabindex="-1">ReLU 不是「不会消失」 <a class="header-anchor" href="#relu-不是「不会消失」" aria-label="Permalink to &quot;ReLU 不是「不会消失」&quot;">​</a></h3><p>负半轴导数为 \\(0\\)，若一个单元对几乎所有样本都为负，它的 \\(W\\) 行收不到梯度，称为死 ReLU。这是另一种消失，只是发生在单元子集上，而不是整层谱半径。学习率过大、偏置过负、输入分布突然偏移，都会制造死单元。Leaky ReLU、GELU 缓解硬零，但不取消「需要非线性」这条。把 ReLU 宣传成消失问题的彻底解决，后课残差与初始化会显得多余。<span class="marginnote">可以把它想象成跳闸的插座：一旦这个单元对所有样本都输出 0，它的梯度也永远是 0，参数再也收不到更新信号——灯不会自己重新亮，除非换激活函数、调小学习率，或靠别的单元把它的输入重新拉回正区间。初学者容易以为&quot;没死透的 ReLU 都能自己活过来&quot;，实际上梯度为 0 就没有任何力量推动它复苏。</span></p><p><span class="marginnote">输出层接 softmax 时，倒数第二层常用 ReLU 或 GELU，而不是再接一个 sigmoid。概率由 softmax 提供；中间层要的是不饱和的增益，不是再做一次单纯形。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MLP 一层：\\(h=\\sigma(Wx+b)\\)。反向：\\(\\mathrm{d}z=\\mathrm{d}h\\odot\\sigma&#39;(z)\\)。ReLU 的 \\(\\sigma&#39;\\) 是指示函数 \\(\\mathbf{1}_{z\\gt 0}\\)（\\(0\\) 点的次梯度取 \\(0\\) 或 \\(1\\) 均可，实现任意约定）。tanh 的 \\(\\sigma&#39;=1-\\tanh^2 z\\)。堆叠 \\(L\\) 层就有 \\(L\\) 次逐元素门，夹在 \\(L\\) 次仿射之间。本课不讨论宽度如何选，那是参数量课。</p>',11)),(r(),o(n,null,{default:e(()=>[s(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AFF%5B%22%E4%BB%BF%E5%B0%84%20Wx%20%E5%8A%A0%20b%22%5D%20--%3E%20SIG%5B%22%E9%A5%B1%E5%92%8C%E6%BF%80%E6%B4%BB%22%5D%0A%20%20AFF%20--%3E%20RELU%5B%22ReLU%22%5D%0A%20%20SIG%20--%3E%20SAT%5B%22%E5%A4%A7%E5%B9%85%E5%80%BC%E6%97%B6%E5%AF%BC%E6%95%B0%E8%BF%91%200%22%5D%0A%20%20RELU%20--%3E%20POS%5B%22%E6%AD%A3%E5%8D%8A%E8%BD%B4%E5%A2%9E%E7%9B%8A%201%22%5D%0A%20%20RELU%20--%3E%20DEAD%5B%22%E8%B4%9F%E5%8D%8A%E8%BD%B4%E6%AD%BB%E5%8D%95%E5%85%83%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,[t("分段线性网络把 \\(\\mathbb{R}^d\\) 切成多面体，每个多面体内仍是仿射，边界由 ReLU 的过零决定。深度增加折点的组合数，这是表达力来源。饱和激活则把表示压进有界盒子，前向不会爆炸，反向却容易没梯度——前向稳定与反向可训不是同一件事。现代前馈默认非饱和（或弱饱和）激活，把有界性交给后课的 LayerNorm，而不是交给 \\(\\sigma\\) 的值域。"),i("span",{class:"marginnote"},'为什么重要：初学者容易以为"输出有界就是好激活"，于是往中间层塞 sigmoid。结果训练不动才发现：前向稳定只是把问题藏起来，反向梯度照样指数缩水；先保证梯度能流回来，再谈稳定性。')],-1)),(r(),o(n,null,{default:e(()=>[s(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LR%5B%22%E5%AD%A6%E4%B9%A0%E7%8E%87%E8%BF%87%E5%A4%A7%22%5D%20--%3E%20ZN%5B%22z%20%E9%95%BF%E6%9C%9F%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20BN%5B%22%E5%81%8F%E7%BD%AE%E8%BF%87%E8%B4%9F%22%5D%20--%3E%20ZN%0A%20%20SHIFT%5B%22%E8%BE%93%E5%85%A5%E5%88%86%E5%B8%83%E7%AA%81%E5%8F%98%22%5D%20--%3E%20ZN%0A%20%20ZN%20--%3E%20G0%5B%22%E5%AF%BC%E6%95%B0%E6%81%92%E4%B8%BA%200%22%5D%0A%20%20G0%20--%3E%20NOG%5B%22%E8%AF%A5%E8%A1%8C%20W%20%E6%94%B6%E4%B8%8D%E5%88%B0%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20NOG%20--%3E%20DEAD%5B%22%E5%8D%95%E5%85%83%E6%B0%B8%E4%B9%85%E5%A4%B1%E6%B4%BB%22%5D%0A%20%20DEAD%20-.-%3E%7C%22%E5%8F%AA%E6%9C%89%E8%BE%93%E5%85%A5%E9%87%8D%E6%96%B0%E5%8F%98%E6%AD%A3%E6%89%8D%E5%8F%AF%E8%83%BD%E5%A4%8D%E6%B4%BB%22%7C%20ZN%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>选择 \\(\\sigma\\) 还改变初始化理论：ReLU 大约一半单元为 \\(0\\)，方差传递与 tanh 不同。下一课专门处理这件事，本课只要求：激活的导数进入增益连乘，选 \\(\\sigma\\) 就是在选默认增益。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GELU 的积分形式，不写门控线性单元。下一课<a href="/llm/why-init">初始化为何需要</a>假定激活已选定，问 \\(W\\) 的尺度。后课默认：MLP 层是仿射加非饱和逐元素激活；说到饱和，是在诊断消失。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无非线性则多层仿射退化成一层；\\(\\sigma\\) 是深度有意义的前提。</li><li>饱和激活在大幅值时掐断反向增益。</li><li>ReLU 正半轴增益为 \\(1\\)，但死单元是局部消失。</li><li>中间层不要用 sigmoid 来「当概率」，概率留给 softmax。</li><li>出处：Nair &amp; Hinton, ICML 2010；Glorot et al., AISTATS 2011。</li></ul>',5))])}const _=m(d,[["render",p]]);export{f as __pageData,_ as default};
